/**
 * Navigation Destination Allowlist & Platform Route Mapping
 * Source of truth for client-side navigation actions generated by AI Assistant.
 */

export type NavigationPlatform = 'web' | 'native';

export interface DestinationRouteConfig {
  id: string;
  labelVi: string;
  webPath: (params?: Record<string, string>) => string;
  nativePath: (params?: Record<string, string>) => string;
}

const buildQueryString = (params?: Record<string, string>): string => {
  if (!params || Object.keys(params).length === 0) return '';
  const searchParams = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value) searchParams.append(key, value);
  }
  const qs = searchParams.toString();
  return qs ? `?${qs}` : '';
};

