/**
 * Resolves a destinationId and params to a platform-safe URL path.
 * Returns null if the destinationId is not on the server-approved allowlist.
 */
export function buildDestinationHref(
  destinationId: string,
  params?: Record<string, string>,
  platform: NavigationPlatform = 'web',
): string | null {
  const config = DESTINATION_CATALOG[destinationId];
  if (!config) {
    if (process.env.NODE_ENV === 'development') {
      console.warn(`[Navigation] DestinationId "${destinationId}" not found in allowlist.`);
    }
    return null;
  }

  return platform === 'native' ? config.nativePath(params) : config.webPath(params);
}
